mapper.select:
SELECT COUNT(*)
FROM archive_access_item item
JOIN archive_access_application application ON application.id = item.application_id
WHERE item.archive_version_id = #{versionId}
  AND (
      (application.status = 'IN_USE'
       AND application.start_at <= #{now}
       AND application.due_at >= #{now}
       AND EXISTS (
           SELECT 1 FROM archive_use_record active_use
           WHERE active_use.application_id = application.id
             AND active_use.returned_at IS NULL
             AND (application.applicant_id = #{userId} OR active_use.operator_id = #{userId})
       ))
      OR (#{canReview} = TRUE AND application.status = 'PENDING_APPROVAL')
  )

SELECT a.id, a.application_no, a.applicant_id, a.department_id, a.purpose, a.use_type, a.start_at, a.due_at, a.status, a.version_no, a.created_at FROM archive_access_application a WHERE a.id = #{id}
AND 1 = 1 AND a.department_id = #{departmentId}
AND EXISTS (SELECT 1 FROM sys_user u WHERE u.id = a.applicant_id AND u.employee_id = #{employeeId})
AND 1 = 0
LIMIT 1

mapper.update:
UPDATE archive_access_application
SET status = #{status}, version_no = #{versionNo}
WHERE id = #{id} AND version_no = #{versionNo} - 1

mapper.select:
SELECT a.id
FROM archive_access_application a
WHERE a.status = 'IN_USE' AND a.due_at < #{now}
  AND EXISTS (
      SELECT 1 FROM archive_use_record u
      WHERE u.application_id = a.id AND u.returned_at IS NULL
  )
ORDER BY a.due_at, a.id
LIMIT #{limit}

SELECT a.id
FROM archive_access_application a
WHERE a.status = 'APPROVED' AND a.due_at < #{now}
ORDER BY a.due_at, a.id
LIMIT #{limit}

mapper.update:
UPDATE archive_access_application
SET status = 'EXPIRED', version_no = version_no + 1
WHERE id = #{id} AND status = 'APPROVED' AND due_at < #{now}

mapper.select:
SELECT a.id, a.application_no, a.applicant_id, a.department_id, a.purpose, a.use_type,
       a.start_at, a.due_at, a.status, a.version_no, a.created_at
FROM archive_access_application a
WHERE 1 = 1
AND a.applicant_id = #{applicantId}
AND a.status = #{status}
AND a.department_id = #{departmentId}

    AND 1 = 1
    AND a.department_id = #{departmentId}

        AND EXISTS (SELECT 1 FROM sys_user u WHERE u.id = a.applicant_id AND u.employee_id = #{scopeEmployeeId})

    AND 1 = 0

ORDER BY a.created_at DESC, a.id DESC
LIMIT #{offset}, #{limit}

